<script setup lang="ts">
import { computed, ref } from 'vue'
import type { Save } from '../game/persistence'
import { accuracy, speed } from '../game/metrics'
import { worlds } from '../data/curriculum'
const props = defineProps<{ save: Save }>()
const emit = defineEmits<{ export: []; import: [file: File]; settings: [settings: Save['settings']]; rename: [name: string] }>()
const fileInput = ref<HTMLInputElement>()
const struggling = computed(() => Object.entries(props.save.totals.keys).filter(([, stat]) => stat.attempts >= 3).sort((first, second) => second[1].errors / second[1].attempts - first[1].errors / first[1].attempts).slice(0, 12))
function importFile(event: Event) { const input = event.target as HTMLInputElement; const file = input.files?.[0]; if (file) emit('import', file); input.value = '' }
</script>
<template>
  <section><div class="page-title"><div><div class="eyebrow">A little progress, every day</div><h1>Keeper’s journal</h1><p>Parent statistics · stored on this browser only</p></div><span class="count-pill">Local profile</span></div>
    <div class="stats-grid"><div class="stat-card"><span>Overall accuracy</span><strong>{{ save.totals.attempts ? (accuracy(save.totals) * 100).toFixed(1) + '%' : '—' }}</strong><small>{{ save.totals.attempts }} printable attempts</small></div><div class="stat-card"><span>Active practice</span><strong>{{ (save.totals.activeMs / 60000).toFixed(1) }} <small>min</small></strong><small>Thinking time included; pauses excluded</small></div><div class="stat-card"><span>Expeditions</span><strong>{{ save.totals.wins }} <small>/ {{ save.totals.expeditions }}</small></strong><small>Completed / finished or retreated</small></div><div class="stat-card"><span>Completed characters</span><strong>{{ save.totals.completed }}</strong><small>No speed minimum for progress</small></div></div>
    <div class="journal-columns"><section class="panel"><h2>Keys to practice</h2><p class="muted">Prompt selection gently favors keys with more errors, within the chosen world.</p><div v-if="struggling.length" class="key-stats"><div v-for="[key, stat] in struggling" :key="key"><kbd>{{ key === ' ' ? 'space' : key }}</kbd><span>{{ stat.errors }} / {{ stat.attempts }} errors</span><meter :value="stat.errors" :max="stat.attempts" :aria-label="`Errors for ${key}`"></meter></div></div><p v-else class="empty-note">Play a few encounters to start your key journal.</p></section>
    <section class="panel"><h2>Your spellbook settings</h2><label class="field-label">Keeper name<input :value="save.name" maxlength="40" @change="emit('rename', ($event.target as HTMLInputElement).value.trim() || 'Keeper')"></label><label class="check-row"><input type="checkbox" :checked="save.settings.keyboard" @change="emit('settings', { ...save.settings, keyboard: ($event.target as HTMLInputElement).checked })"> Show keyboard guide</label><label class="check-row"><input type="checkbox" :checked="save.settings.reducedMotion" @change="emit('settings', { ...save.settings, reducedMotion: ($event.target as HTMLInputElement).checked })"> Reduce motion</label><p class="fine-print">System reduced-motion preferences are always respected.</p><div class="button-row"><button class="button" @click="emit('export')">↓ Export save</button><button class="button" @click="fileInput?.click()">↑ Import save</button><input ref="fileInput" type="file" accept="application/json,.json" hidden @change="importFile"></div><p class="fine-print">Import replaces this profile. Export a backup first. No account or cloud sync.</p></section></div>
    <section class="panel history-panel"><h2>Expedition history</h2><div class="table-scroll"><table><thead><tr><th>Date</th><th>World</th><th>Outcome</th><th>Accuracy</th><th>Speed</th><th>Active time</th></tr></thead><tbody><tr v-for="run in save.runs" :key="run.id"><td>{{ new Date(run.date).toLocaleDateString() }}</td><td>{{ worlds[run.world]!.name }}</td><td>{{ run.won ? 'Egg earned' : 'Retreated' }}</td><td>{{ (accuracy(run) * 100).toFixed(1) }}%</td><td>{{ speed(run, run.world === 0).toFixed(1) }} {{ run.world === 0 ? 'CPM' : 'WPM' }}</td><td>{{ (run.activeMs / 1000).toFixed(0) }}s</td></tr></tbody></table><p v-if="!save.runs.length" class="empty-note">Your first adventure is waiting.</p></div><p class="fine-print">The most recent 100 results are kept. Lifetime totals include unfinished practice checkpoints. Speeds use completed characters, not corrected keystrokes.</p></section>
  </section>
</template>
